body.onloadscript:



if (Sepoa.request.SMR_NUMBER && !Sepoa.request.SCREEN_TYPE) {
    doQuery(Sepoa.request.SMR_NUMBER, 'Y');
}
window.onresize = resizePopup;

//링크접속일경우 파라미터값이 존재함 으로 넘어옴
if (Sepoa.request.SCREEN_TYPE) {
    screenType = true;
    screenFlag = Sepoa.request.RE_FLAG;
} else {
    screenType = false;
}

userscript.function:

switch (name) {
    case "SAVE":
        doSave();
        break;
    case "REAL_SEAL":
        doRealSave();
        break;
    case "APPROVAL_REQ":
        doApprovalRequest();
        break;
    case "LEGAL_REQUEST":
        doLegalRequest();
        break;
    case "LEGAL_ACCEPT":
        doLegalAccept();
        break;
    case "LEGAL_REJECT":
        doLegalReject();
        break;
    case "BACK":
        doBack();
        break;
    case "COMPLETE":
        doComplete();
        break;
    case "DECIDE_REQUEST":
    	doDecideRequest();
    	break;
    case "DECIDE_ACCEPT":
    	doDecideAccept();
    	break;
    case "DECIDE_REJECT":
    	doDecideReject();
    	break;
    default:
        break;
}


            // 채번 따서 $reqSealInfo에 채번넣고 기본셋팅
            $documentList = new Object();
            $selectedSealList = new Object();

            formObj.setValue('APPLY_TYPE', 'C');
            gridObj_title.innerHTML = Sepoa.cache.text.get('SLM_211.GRID_TITLE');
            gridObj_title.setAttribute('style', 'font-size:14px;padding-top: 15px;');
            gridObj2_title.innerHTML = Sepoa.cache.text.get('SLM_211.GRID_1_TITLE');
            gridObj2_title.setAttribute('style', 'font-size:14px;padding-top: 15px;');
            gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_TYPE_U'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_NAME'), false);
            gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_NUMBER'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('OTHER_FILE_IMG'), true);
            formObj2.setValue('FOOTER_FLAG', 1);

            $(approver_grid_cont).hide();

            if(!sUtils.workflow.check('CERT1686730093044')) {
	            gridObj2.setColumnHidden(gridObj2.getColIndexById('COUNT'), true);
            }
            gridObj2.setColumnHidden(gridObj2.getColIndexById('CALC_DOWN_CNT'), 1); // 다운로드 가능 횟수

            if (!sUtils.workflow.check('US1638852635132')) {
                gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
                //gridObj.grid_required[gridObj.getColIndexById('COUNT')] = '';
            }

            if (!sUtils.workflow.check('US1682656641829')) { //카테고리, 공통인감 여부 셋팅
                gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_CATEGORY'), 1); //카테고리 숨김
            }

            //교부서류 부수 제한 사용 여부 확인
            if(!sUtils.workflow.check('CERT1686730093044')) {
	            gridObj2.setColumnHidden(gridObj2.getColIndexById('COUNT'), true);
            }

            //전자 법인인감 모듈
            if (!sUtils.workflow.check('CS1639451323063')) {
                formObj.hideItem("ELECTRON_FLAG");
                formObj.checkItem('REAL_FLAG');
            }

            //실물 법인인감 모듈
            if (!sUtils.workflow.check('CS1639451376543')) {
                formObj.hideItem("REAL_FLAG");
                formObj.checkItem('ELECTRON_FLAG');
            }

            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectBasicCorpSeal', {
                SEAL_TYPE: 'C'
            }, function(so) {
                if (so.status == 1) {
                    $corpSealList = JSON.parse(so.result[0]);
                    if (!Sepoa.request.SMR_NUMBER) {
                        isNew = true;
                        var smrNumber = getDocumentNumber("SMR"); //채번
                    } else {
                        isNew = false;
                        var smrNumber = Sepoa.request.SMR_NUMBER;
                    }
                    $reqSealInfo.SMR_NUMBER = smrNumber;
                    formObj.setValue('SMR_NUMBER', smrNumber);

                    var SEAL_C_CategoryCodeArr = [];
                    var SEAL_C_CategoryNameArr = [];
                    var SEAL_C_NameArr = [];
                    var SEAL_C_ManageNumber = [];

                    for (var i in $corpSealList) {
                        SEAL_C_CategoryCodeArr.push($corpSealList[i].SEAL_CATEGORY);
                        SEAL_C_CategoryNameArr.push($corpSealList[i].SEAL_CATEGORY_NAME);
                        SEAL_C_NameArr.push($corpSealList[i].SUBJECT);
                        SEAL_C_ManageNumber.push($corpSealList[i].MANAGE_NUMBER);
                    }

                    dataOutput.setValue("SEAL_C_CODE_ARR", SEAL_C_CategoryCodeArr);
                    dataOutput.setValue("SEAL_C_NAME_ARR", SEAL_C_CategoryNameArr);
                    dataOutput.setValue("SEAL_NAME_ARR", SEAL_C_NameArr);
                    dataOutput.setValue("SEAL_NAME_QUANT", SEAL_C_NameArr.length - 1);
                    defaultCorpSeal = SEAL_C_ManageNumber;

                    if (sUtils.ux.getRootScreenID() == 'SLM_210') {
                        initBtn();
                        if (!Sepoa.request.SMR_NUMBER) {
                            doAddRow();
                        }
                    }
                } else {
                    Alert(so.message);
                    return;
                }
            });


btnObj.forEachBtn(function(btnId) {
    if (btnId) {
        btnObj.showButton(btnId, false);
    }
});
gridObj_btnObj.forEachBtn(function(btnId) {
    if (btnId) {
        gridObj_btnObj.showButton(btnId, false);
    }
});
gridObj2_btnObj.forEachBtn(function(btnId) {
    if (btnId) {
        gridObj2_btnObj.showButton(btnId, false);
    }
});
gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 1);


document.getElementById('elrxbmeQPHybmeIizh').style.display = 'inline-block';
document.getElementById('elrxbmerQbBcmetaZG').style.display = 'inline-block';
document.getElementById('elrxbmeotICcmeIYbT').style.display = 'inline-block';


            hideAllButtons();
            gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_TYPE_C'), 0);
            if (SCREEN_MODE == 'APP') {
                formObj.setViewMode(true);
                formObj.setdisable('SEAL_USE_TYPE_IMG', false);
                formObj._apiConnector('detachAllEvents', []);
                formObj2.setViewMode(true);
                gridObj.setReadOnly(true);
                gridObj2.setReadOnly(true);
                showButtonArea();
            } else if (['', Sepoa.info.ID].indexOf(formObj.getValue('ADD_USER_ID')) > -1 && (smrStatus == 'T' || (SCREEN_MODE == 'MY_REQ' && VIEW_MODE == 'EDITOR'))) { //임시저장 또는 요청내역에서 수정하는 경우
                VIEW_MODE == 'EDITOR';
                formObj.setViewMode(false);
                formObj.setdisable('SEAL_USE_TYPE_IMG', false);
                formObj2.setViewMode(false);
                gridObj.setReadOnly(false);
                gridObj2.setReadOnly(false);
                //gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 0);
                gridObj.setColumnHidden(gridObj.getColIndexById('SELECTED'), 0);
                gridObj2.setColumnHidden(gridObj2.getColIndexById('SELECTED'), 0);

            	if(smrStatus == 'T'){
            		gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), 1);
            	}

                if (SCREEN_MODE == 'GW' || moveFlag == 'N') {
                    btnObj.showButton('back', true);
                }

            	if (formObj.getValue('REAL_FLAG') == 1) {
                   gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
                   gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 1);
                }

                doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectNextModule', {
                    ALIAS: 'CREATE',
                    PARENT: 'CSW'
                }, function(so) {
                    if (so.status == 1) {
                        var moduleArr = JSON.parse(so.result[0]);
                        var nextModule = moduleArr.MODULE;
                        gridObj_btnObj.showButton('rowadd,rowdelete', true);
                        gridObj2_btnObj.showButton('rowadd_1,rowdelete_1', true);
                        switch (nextModule) {
                            case "CSW1635988016443":
                                // 결재
                                btnObj.showButton('save,approval_req', true);
                                break;
                            case "CSW1635988016964":
                                // 인감책임자 승인
                                btnObj.showButton('save,legal_request', true);
                                break;
                            case "CSW1635988019236":
                                // 완료
                                btnObj.showButton('save,complete', true);
                                break;
                            default:
                                break;
                        }
                        showButtonArea();
                    } else {
                        Alert(Sepoa.cache.text.get("MESSAGE.1002"));
                    }
                });
            } else if (smrStatus != 'T' || ['', Sepoa.info.ID].indexOf(formObj.getValue('ADD_USER_ID')) == -1) {
                var alias = '';
                formObj.setViewMode(true);
                formObj.setdisable('SEAL_USE_TYPE_IMG', true);
                formObj2.setViewMode(true);
                gridObj.setReadOnly(true);
                gridObj2.setReadOnly(true);
                gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 1);
                gridObj.setColumnHidden(gridObj.getColIndexById('SELECTED'), 1);
                gridObj2.setColumnHidden(gridObj2.getColIndexById('SELECTED'), 1);
                gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 1);
                if (SCREEN_MODE == 'TODO' || Sepoa.request.SCREEN_MODE == 'TODO') {
                    if (smrStatus == 'G' && Sepoa.info.CTRL_CODE.indexOf('SEAL_CONFIRM') > -1) {
                        btnObj.showButton('legal_accept,legal_reject', true);
                    }
                    if (smrStatus == 'DW' && btnFlag) {
                        btnObj.showButton('decide_accept,decide_reject', true);
                    }
                }
                if (formObj.getValue('REAL_FLAG') == 1) {
                    gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
                    gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 1);

                    if(sUtils.workflow.check('CSW1687399123985')){
                    	if (smrStatus == 'C' || smrStatus == 'DR') {
                    		btnObj.showButton('decide_request', true);
                    	}
                    }

                    if (['C','DW','DC','DR'].indexOf(smrStatus) > -1) {
                        //btnObj.showButton('real_seal', true);
                        gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 0);
                        gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), false);
                        gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), true);
                        gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 1);
                    }
                } else if (formObj.getValue('ELECTRON_FLAG') == 1) {
                    if (smrStatus == 'C') {
                        gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 0);
                        gridObj2.setColumnHidden(gridObj2.getColIndexById('TEMPLATE_DATA'), 1);
                        gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
                        if (!sUtils.workflow.check('US1638852635132')) {
                            gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 1);
                        } else {
                            gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 0);
                        }
                    }
                }

                showButtonArea();
                if (Sepoa.request.SMR_NUMBER || ['APPR_TURN', 'APPR_DONE', 'APPR_REFER'].indexOf(SCREEN_MODE) > -1) {
                    btnObj.showButton('back', false);
                    btnObj.showButton('real_seal', false);
                    $(approver_grid_cont).hide();
                } else if (SCREEN_MODE == 'ATTACH_CONFIRM') {
                    btnObj.showButton('real_seal', false);
                    btnObj.showButton('back', true);
                } else {
                    btnObj.showButton('back', true);
                }
            }

            if (!sUtils.workflow.check('CSW1635988017548')) {
                // 교부서류 안쓰면 교부서류 관련 그리드와 영역 숨김처리
                $('#ZgvlvOfHyAnvOfaayC').hide();
                $('#ZgvlvOfHyAnvOfNrKJ').hide();
                $('#FOYtSteOidtSteaJNx').hide();
                $('#elrxbmevzvzbmehyDo').hide();
            }


             else if (screenType && (smrStatus == 'R' || smrStatus == 'C')) {
                    // 메일링크접속 일경우 이면서 smrStatus가 완료, 반려일때 버튼숨김처리.
                    callFunction('AP_111', 'btn_false', null);
                } 


            if (screenType) { //메일로 들어왔을 경우
	            	$(approver_grid_cont).hide();// 상단 그리드 표출 숨김처리
	                btnObj.showButton('back', false);
	               	gridObj.setColumnHidden(gridObj.getColIndexById('SELECTED'), 1); // 결재진행중일때 필요없음                

	                if(screenFlag == 'R'){
	                	gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1); // 실물일때 필요없음
	                	if(smrStatus == 'C'){
	                		gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), false); // 실물이 완료 됬을때 필요
	                	}
	                }else{
	                	//
	                	if(sUtils.workflow.check('US1638852635132')) { 
		                	gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 0); 
	                	}else{
	                		gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
	                	}
	                }

	                if(smrStatus == 'R' || smrStatus == 'C'){
	                	// 메일링크접속 일경우 이면서 smrStatus가 완료, 반려일때 버튼숨김처리
	                    callFunction('AP_111', 'btn_false', null);
	                }

	                if ( smrStatus == 'DR' || smrStatus == 'DC'){
                    	btnObj.showButton('decide_accept,decide_reject,decide_request', false);
                	}

	                if(sUtils.workflow.check('USW1665473167170')) { //증명서 발급 모듈이 켜져 있을 경우 
		                gridObj2.setColumnHidden(gridObj2.getColIndexById('SELECTED'), 1); //교부서류 
		                if (smrStatus == 'C') {
		                    gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 0);
		                }
	                }
				}


            $documentList = {};
            $reqSealInfo = {};
            formObj.clear();
            formObj2.clear();
            gridObj.clearAll();
            gridObj2.clearAll();
            moveFlag = flag;
            VIEW_MODE = viewMode || '';
            isNew = false;

            if (smrNumber) {
                $reqSealInfo.SMR_NUMBER = smrNumber;
                formObj.setValue('SMR_NUMBER', smrNumber);
            }

            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectRequestInfo', {
                SMR_NUMBER: smrNumber,
                APPLY_TYPE: 'C'
            }, function(so) {
                if (so.status == 1) {
                    var reqData = JSON.parse(so.result[0]);
                    var reqSealInfo = reqData[0].REQ_SEAL_INFO;
                    var documentList = reqData[0].DOCUMENT_LIST;
                    var selectedSealList = reqData[0].SELECTED_SEAL_LIST;
                    var attachList = reqData[0].ATTACH_DOCUMENT_LIST;
            		var btnFlag = false;

                    for (var i in selectedSealList) {
                        if (selectedSealList[i].ITEM_CODE == 'U') {
                            allUseSealObj[selectedSealList[i].MANAGE_NUMBER] = selectedSealList[i];
                        }
                    }

                    formObj.dataMapper(reqSealInfo, 'JSON');
                    formObj2.dataMapper(reqSealInfo, 'JSON');
                    formObj.setValue('FORM_REMARK', formObj2.getValue('REMARK')); // 비고 란을 문서근거번호로 전달
                    $reqSealInfo.SMR_NUMBER = reqSealInfo.SMR_NUMBER;
                    if (screenType) {
                        var headerText = formObj.getValue('SUBJECT');
                        callFunction('AP_110', 'chageHeaderText', [headerText])
                    }

                    smrStatus = reqSealInfo.SMR_STATUS;

                    if (smrStatus == 'T' && ['', Sepoa.info.ID].indexOf(reqSealInfo.ADD_USER_ID) > -1) {
                        VIEW_MODE = 'EDITOR';
                    }

                    if (smrStatus != "T" && VIEW_MODE != "APP" && sUtils.workflow.check('SID1678431100493') && !sUtils.workflow.check('CSW1635988016964')) {
                    	//임시저장X, 결재선 라인표출 on, 인감책임자 승인모듈 off 일 경우
                        $(approver_grid_cont).show();
                        doQueryApprover(reqSealInfo.SMR_NUMBER);
                    } else {
                        $(approver_grid_cont).hide();
                    }

                    // 구분 세팅
                    var reFlagDetail = reqSealInfo.RE_DETAIL.split(',');
                    for (var i in reFlagDetail) {
                        switch (reFlagDetail[i]) {
                            case "E":
                                formObj.setValue('ELECTRON_FLAG', 1);
                                continue;
                            case "R":
                                formObj.setValue('REAL_FLAG', 1);
                                if (sUtils.workflow.check('CSW1681102812928')) gridObj.setColumnHidden(gridObj.getColIndexById('OTHER_FILE_IMG'), false);
                                continue;
                        }
                    }



                    // 용도 세팅
                    var useArray = Sepoa.cache.combo.get('SL0047,' + Sepoa.info.HOUSE_CODE + '#' + Sepoa.info.COMPANY_CODE);
                    var useName = useArray.find((item, idx) => {
                        return item.value == reqSealInfo.REQ_SEAL_USE_TYPE;
                    });
                    formObj.setValue('USE_NUMBER', useName.text);
                    formObj.setValue('SEAL_USE_TYPE', useName.value);
                    // 법적효력문구 세팅
                    var legalWatermark = reqSealInfo.LEGAL_WATERMARK;
                    if (legalWatermark == 'K') {
                        formObj2.setValue('FOOTER_FLAG', 1);
                    } else if (legalWatermark == 'E') {
                        formObj2.setValue('FOOTER_FLAG_EN', 1);
                    }

                    // 날인대상서류 세팅
                    for (var i in documentList) {
                        var data = documentList[i];
                        var maxRowId = dhx4.newId();
                        gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SMR_SEQ_TEMP')).setValue('temp_' + maxRowId);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SMD_NUMBER')).setValue(data.SMD_NUMBER);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('COUNT')).setValue(data.COUNT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('DOWN_COUNT')).setValue(data.DOWN_COUNT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SUBJECT')).setValue(data.SUBJECT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_TYPE_C')).setValue(data.SEAL_TYPE);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_NO')).setValue(data.REAL_ATTACH_NO);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('OTHER_FILE_NO')).setValue(data.OTHER_FILE_NO);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).setValue(data.SMR_NUMBER + '_' + data.SMD_NUMBER);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('CALC_DOWN_CNT')).setValue(Number(data.COUNT) - Number(data.DOWN_COUNT) + ' / ' + Number(data.COUNT));
                        gridObj.cells(maxRowId, gridObj.getColIndexById('ITEMS_JSON')).setValue(data.ITEMS_JSON.replace(/\"/gi, '~REPTOQM~'));
                        gridObj.cells(maxRowId, gridObj.getColIndexById('MARK_COUNT')).setValue(data.MARK_COUNT);

                        var booleanData = searchFMFI(data.SMR_NUMBER + '_' + data.SMD_NUMBER, 'REQ_SEAL');
                        if (booleanData) {
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
                        } else {
                            gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).setValue('');
                        }

                        if (sUtils.workflow.check('CSW1688921063828')) {

							booleanData = searchFMFI(data.SMR_NUMBER + '_' + data.SMD_NUMBER, 'REQ_SEAL_REAL_DOC');
							if(booleanData){
								gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_IMG')).setIcon('ATTACH_IMG2');
	                            gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_IMG')).cell.children[0].style = 'filter:none';
							}

                    	} else if(data.REAL_ATTACH_CNT > 0) {
                    		gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_IMG')).setIcon('ATTACH_IMG2');
							gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_IMG')).cell.children[0].style = 'filter:none';
                    	}

                        if (data.OTHER_FILE_CNT > 0) {
                            gridObj.cells(maxRowId, gridObj.getColIndexById('OTHER_FILE_IMG')).setIcon('ATTACH_IMG2');
                            gridObj.cells(maxRowId, gridObj.getColIndexById('OTHER_FILE_IMG')).cell.children[0].style = 'filter:none';
                        }

                        gridObj.showRow(maxRowId);

                        $documentList[data.SMD_NUMBER] = data;
                        $selectedSealList[data.SMD_NUMBER] = {};
                        var sealData = [];
                        for (var j in selectedSealList) {
                            if (data.SMD_NUMBER == selectedSealList[j].SMD_NUMBER) {
                                selectedSealList[j].ITEM_NAME = selectedSealList[j].SUBJECT;
                                sealData.push(selectedSealList[j]);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT")).setValue(selectedSealList[j].DEPT_NAME);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT_CODE")).setValue(selectedSealList[j].SEAL_MG_DEPT);

            					if(sUtils.workflow.check('CSW1687399123985')){
            						if( smrStatus == 'DW' && Sepoa.info.ID == selectedSealList[j].SEAL_MG_USER_ID && selectedSealList[j].DEC_FLAG == 'N' ||
            					  		smrStatus == 'DW' && Sepoa.info.ID == selectedSealList[j].RECE_USER_ID && selectedSealList[j].DEC_FLAG == 'N'){
            					  		btnFlag = true;	
            						}
            					}

                                var orgSealName = gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_NAME")).getValue();
                                var sealName = selectedSealList[j].SUBJECT;
                                if (orgSealName != '') sealName = orgSealName + ',' + sealName;
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_NAME")).setValue(sealName);

                                var orgManageNo = gridObj.cells(maxRowId, gridObj.getColIndexById("MANAGE_NUMBER")).getValue();
                                var manageNo = selectedSealList[j].MANAGE_NUMBER;
                                if (orgManageNo != '') manageNo = orgManageNo + ',' + manageNo;
                                gridObj.cells(maxRowId, gridObj.getColIndexById("MANAGE_NUMBER")).setValue(manageNo);

                                var orgCategoryCode = gridObj.cells(maxRowId, gridObj.getColIndexById("CATEGORY_CODE")).getValue();
