let allowExtensions;
if(!sUtils.string.isBlank(Sepoa.config.get('req.seal.upload.allow.extension'))){
	allowExtensions = Sepoa.config.get('req.seal.upload.allow.extension').split(',');
} else {
	allowExtensions = ['pdf', 'PDF', 'docx', 'doc', 'ppt', 'pptx', 'hwp', 'hwpx'];
}
const fileName = files[0].name;
const lastDotIdx = fileName.lastIndexOf('.');
if (lastDotIdx == -1) {
    Alert('첨부가 제한된 확장자입니다');
    return false;
} else {
    const ext = fileName.slice(lastDotIdx + 1);
    if (allowExtensions.indexOf(ext) == -1) {
        Alert(sUtils.string.dataReplacer(sUtils.cache.text.get("BASE_FILE.NOT_SUPPORT_EXT"), {
            EXT: ext
        }));
        return false;
    }
}

